export const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeUrl(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
export const storageKey=id=>`hydra-stack-demo-v1:${id}`;
export const initialState=profile=>({profile:structuredClone(profile),leads:{},meetings:[],drafts:{},onboarded:false});
export function updateLead(state,id,changes){return {...state,leads:{...state.leads,[id]:{...state.leads[id],...changes}}};}
export function eligibility(job,profile){if(job.id==='anduril-finance-data-2027'&&(profile.graduation<'2027-12'||profile.graduation>'2028-06'))return 'Graduation mismatch: snapshot asks for December 2027–June 2028. Confirm with the employer.';return job.start==='August 2027'?'August 2027 start is stated in the snapshot. Confirm programme eligibility and availability.':'Start timing is unconfirmed. Do not assume compatibility with your graduation date.';}
export function rankJobs(list,profile){return list.map(j=>{const matched=j.tags.filter(t=>profile.skills.some(s=>s.toLowerCase()===t.toLowerCase()));let score=matched.length*3;if(profile.focus.startsWith('Marketing')&&j.tags.includes('Marketing'))score+=5;if(profile.focus.startsWith('Finance')&&j.tags.includes('Finance'))score+=5;if(profile.focus.startsWith('Data')&&j.tags.includes('SQL'))score+=5;if(j.region===profile.location)score+=1;if(j.start==='August 2027')score+=1;if(j.id==='anduril-finance-data-2027'&&(profile.graduation<'2027-12'||profile.graduation>'2028-06'))score-=20;return {...j,score,reasons:matched.length?matched.map(s=>`${s} overlaps with your profile`):['Explore this adjacent career path'],fit:score>=10?'Strong skill overlap':score>=5?'Worth exploring':'Adjacent opportunity'};}).sort((a,b)=>b.score-a.score);}
export function connectionDraft(person,profile){const first=profile.name.split(' ')[0];return `Hi ${person.name.split(' ')[0]}, I’m ${first}, studying ${profile.degree.replace('Business Administration','Business')} at ${profile.university}. I’m exploring ${profile.focus.toLowerCase()} and would value connecting.`.slice(0,200);}
export function followupDraft(person,profile){return `Thanks for connecting, ${person.name.split(' ')[0]}. Your public profile lists a talent acquisition role at ${person.company}, which caught my attention as I explore ${profile.focus.toLowerCase()}. I’m studying ${profile.degree} at ${profile.university}, with a focus on ${profile.skills.slice(0,2).join(' and ')}. I’m trying to understand how to prepare a useful portfolio before graduation. From your perspective, what is one skill or example of work that helps an early-career candidate stand out in your area?`;}

export const selectEvidence=(all,ids)=>ids.map(id=>all.find(e=>e.id===id)).filter(Boolean);
export const storageNotice=(message,persistent)=>persistent?message:message+" Session only: browser storage is unavailable. Export before closing.";
